button:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.required-field::after {
  content: ' *';
  color: var(--color-danger);
}

.card {
  transition: transform 150ms ease, box-shadow 150ms ease;
}
.card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

@media (prefers-reduced-motion: reduce) {
  .card {
    transition: none;
  }
}

@mixin respond-to($breakpoint) {
  @media (min-width: map.get($breakpoints, $breakpoint)) {
    @content;
  }
}

@function spacing($steps) {
  @return $steps * 0.25rem;
}

.card {
  padding: spacing(4); // 1rem

  @include respond-to(desktop) {
    padding: spacing(6); // 1.5rem
  }
}

@use 'sass:map';

$spacing: (1: 0.25rem, 2: 0.5rem, 3: 0.75rem, 4: 1rem);

@each $step, $value in $spacing {
  .m-#{$step} { margin: $value; }
  .p-#{$step} { padding: $value; }
}

@function space($step) {
  @return map.get($spacing, $step);
}

const trigger = document.activeElement;
dialog.showModal();
dialog.querySelector('h2, input, button')?.focus();
dialog.addEventListener('close', () => trigger?.focus(), { once: true });

:root {
  --color-text: #1b1b1b;
  --color-surface: #ffffff;
  --color-focus: #005fcc;
  --color-error: #b00020;
}
:focus-visible { outline: 3px solid var(--color-focus); outline-offset: 2px; }

.dashboard { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 1rem; }
.summary { grid-column: span 3; }
.transactions { grid-column: 1 / -1; }
@media (max-width: 48rem) {
  .summary { grid-column: span 6; }
}
@media (max-width: 30rem) {
  .summary { grid-column: 1 / -1; }
}

.card-list { display: grid; gap: 1rem; }
@media (min-width: 48rem) { .card-list { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 75rem) { .card-list { grid-template-columns: repeat(4, 1fr); } }

.account-widget { container-type: inline-size; }
.account-content { display: grid; gap: .75rem; }
@container (min-width: 32rem) {
  .account-content { grid-template-columns: 1fr auto; align-items: center; }
}

@layer reset, base, components, utilities;
@layer components { .button { padding: .75rem 1rem; } }
@layer utilities { .u-hidden { display: none !important; } }

@layer reset, tokens, base, components, overrides;
@import url('./vendor.css') layer(reset);
@layer components { .account-card { background: var(--surface-card); } }

:root { --z-header: 10; --z-overlay: 100; --z-modal: 1000; }
.app-header { position: sticky; top: 0; z-index: var(--z-header); }
.modal-layer { position: fixed; inset: 0; z-index: var(--z-modal); }

.transaction-card {
  content-visibility: auto;
  contain-intrinsic-size: 280px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; }
}

:root { color-scheme: light dark; --surface: #fff; --text: #171717; }
[data-theme="dark"] { --surface: #121212; --text: #f5f5f5; }
body { background: var(--surface); color: var(--text); }

@media (forced-colors: active) {
  .button { border: 1px solid ButtonText; forced-color-adjust: auto; }
  .focus-ring { outline: 2px solid Highlight; }
}

.card { padding-inline: 1rem; margin-block: .75rem; }
.icon-next { transform: rotate(0deg); }
:dir(rtl) .icon-next { transform: rotate(180deg); }

.table-scroll { overflow-x: auto; overscroll-behavior-inline: contain; }
table { min-width: 48rem; border-collapse: collapse; }
th { position: sticky; top: 0; background: Canvas; }

@use 'tokens' as t;
.account-card {
  color: var(--text-primary);
  padding: t.$space-4;
  &__title { font: t.$heading-sm; }
  &--warning { border-color: var(--border-warning); }
}

$spacing-unit: 0.25rem; // compile-time
:root { --surface-card: #fff; --text-primary: #111; } // runtime
.card { padding: $spacing-unit * 4; background: var(--surface-card); color: var(--text-primary); }

// _tokens.scss
$space-4: 1rem;
// component.scss
@use 'tokens' as t;
.card { padding: t.$space-4; }

@space-4: 1rem;
.account-card {
  padding: @space-4;
  &__title { font-weight: 600; }
}

.account-card {
  &__header { /* one component level */ }
  &__action { /* avoid .page .panel .card ul li button */ }
}

@media print {
  nav, .actions { display: none !important; }
  main { max-width: none; }
  table { break-inside: auto; }
  tr { break-inside: avoid; }
  @page { margin: 16mm; }
}

